'use strict';
// Keep the same editor DOM and selection when the user pins the laboratory.
const lab=document.querySelector('.lab'),pinButton=document.querySelector('#pin-lab');
const labSpace=document.createElement('div');labSpace.hidden=true;lab.before(labSpace);
function updatePinnedSpace(){document.body.style.setProperty('--pinned-height',lab.classList.contains('is-pinned')?lab.offsetHeight+'px':'0px')}
pinButton.addEventListener('click',()=>{const pinned=!lab.classList.contains('is-pinned');if(pinned)labSpace.style.height=lab.getBoundingClientRect().height+'px';labSpace.hidden=!pinned;lab.classList.toggle('is-pinned',pinned);document.body.classList.toggle('has-pinned-lab',pinned);pinButton.setAttribute('aria-pressed',String(pinned));pinButton.textContent=T(pinned?'Soltar digitação':'Fixar digitação');updatePinnedSpace();if(!pinned)lab.scrollIntoView({block:'nearest',behavior:'instant'})});
new ResizeObserver(updatePinnedSpace).observe(lab);

// Exact outlines exported from all 404 glyphs in ELiS26-Regular. No inferred keyboard entries.
let catalogPromise;
async function showAllGlyphs(){category='todos';document.querySelectorAll('.category-nav button').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.category==='todos')));const root=document.querySelector('#map-content');root.replaceChildren();const intro=document.createElement('p');intro.className='map-explanation';intro.textContent=T('Carregando o repertório completo…');root.append(intro);try{catalogPromise??=fetch('glyph-catalog.json').then(r=>{if(!r.ok)throw new Error();return r.json()});const catalog=await catalogPromise;if(category!=='todos'||searchField.value.trim())return;intro.textContent=T('404 glifos da fonte Regular: entradas, combinações, variantes automáticas e caracteres de apoio. Os desenhos são os contornos originais da fonte. Cartões com tecla abrem os detalhes, e as combinações vão direto para o laboratório. Variantes sem entrada própria são apenas para consulta. Este inventário não é a lista de visografemas do sistema ELiS.');
for(const [title,test] of [[T('Entradas e combinações'),g=>g.entry!==undefined&&g.entry!==null],[T('Variantes e caracteres de apoio'),g=>g.entry===undefined||g.entry===null]]){const group=document.createElement('div');group.className='map-group';const heading=document.createElement('h3');const subset=catalog.filter(test);heading.textContent=title+' · '+subset.length;const grid=document.createElement('div');grid.className='glyph-grid catalog-grid';for(const g of subset){const available=g.entry!==undefined&&g.entry!==null;const card=document.createElement(available?'button':'div');card.className='glyph-card catalog-card';if(available){card.type='button';card.addEventListener('click',()=>{if(!window.openKeyDetails?.(g.entry,card))insert(g.entry)});card.setAttribute('aria-label',T(g.entry.length===1?'Ver detalhes: {0}':'Inserir {0}',entryName(g.entry)))}const svg=document.createElementNS('http://www.w3.org/2000/svg','svg');svg.setAttribute('viewBox',g.box.join(' '));svg.setAttribute('aria-hidden','true');const path=document.createElementNS(svg.namespaceURI,'path');path.setAttribute('d',g.path);path.setAttribute('transform','scale(1,-1)');svg.append(path);card.append(svg);const label=document.createElement(available?'kbd':'span');label.className=available?'':'glyph-label';label.textContent=available?(g.entry===' '?T('Espaço'):g.entry):g.name==='.notdef'?T('Caractere ausente'):T('Sem tecla própria');card.append(label);const name=document.createElement('span');name.className='catalog-name';name.textContent=g.name;card.append(name);grid.append(card)}group.append(heading,grid);root.append(group)}}catch{if(category==='todos'){intro.textContent=T('Não foi possível carregar o repertório. Selecione Todos novamente para tentar.');catalogPromise=null}}}
const allButton=document.createElement('button');allButton.type='button';allButton.textContent=T('Todos');allButton.dataset.category='todos';allButton.setAttribute('aria-pressed','false');allButton.addEventListener('click',()=>showCategory('todos'));document.querySelector('.category-nav').prepend(allButton);

const motionDescriptions=[
T('01 · Configuração de dedos – tg: polegar e demais dedos estendidos, na descrição do exemplo de Barros.'),
T('02 · Orientação da palma – ç: palma voltada para trás.'),
T('03 · Ponto de articulação – Q: a mão se posiciona à frente do rosto. Não há indicação de contato.'),
T('04 · Movimento – Ä: fechar os dedos um a um, sem repetição (tamborilar).')];
let motionStep=0,motionTimer=null;
const playButton=document.querySelector('#motion-play');
function showMotionStep(n){motionStep=n;document.querySelectorAll('[data-part]').forEach(el=>el.classList.toggle('active',Number(el.dataset.part)===n));document.querySelectorAll('[data-step]').forEach(el=>el.setAttribute('aria-pressed',String(Number(el.dataset.step)===n)));document.querySelector('#motion-description').textContent=motionDescriptions[n]}
function stopMotion(){clearTimeout(motionTimer);motionTimer=null;playButton.textContent=T('Reproduzir leitura');playButton.setAttribute('aria-pressed','false')}
function advanceMotion(){motionTimer=setTimeout(()=>{if(motionStep===3){stopMotion();return}showMotionStep(motionStep+1);advanceMotion()},3200)}
playButton.addEventListener('click',()=>{if(motionTimer!==null){stopMotion();return}showMotionStep(0);playButton.textContent=T('Pausar leitura');playButton.setAttribute('aria-pressed','true');advanceMotion()});
document.querySelectorAll('[data-step]').forEach(button=>button.addEventListener('click',()=>{stopMotion();showMotionStep(Number(button.dataset.step))}));
document.querySelector('#motion-insert').addEventListener('click',()=>{insert('tgçQÄ');if(!lab.classList.contains('is-pinned'))lab.scrollIntoView({block:'center',behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth'});input.focus({preventScroll:true})});
document.addEventListener('visibilitychange',()=>{if(document.hidden)stopMotion()});showMotionStep(0);
